.cbf-invoice-review-queue__grid .cbf-grid-status {
  display: inline-flex;
  align-items: center;
  height: 100%;
}
.cbf-invoice-review-queue__grid .cbf-grid-num,
.cbf-invoice-review-queue__grid .cbf-grid-num .ag-header-cell-label {
  justify-content: flex-end;
  text-align: right;
  font-variant-numeric: tabular-nums;
}
.cbf-invoice-review-queue__grid .cbf-grid-id {
  font-variant-numeric: tabular-nums;
  color: var(--color-content-default-secondary);
}
.cbf-invoice-review-queue__grid .cbf-grid-idcell {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-200);
  height: 100%;
}
.cbf-invoice-review-queue__grid .cbf-grid-muted {
  color: var(--color-content-default-tertiary);
}
.cbf-invoice-review-queue__grid .cbf-grid-overdue {
  color: var(--color-background-utility-danger, #b42318);
  font-weight: var(--typography-font-weight-medium);
}
.cbf-invoice-review-queue__grid .ag-row {
  cursor: pointer;
}
.cbf-invoice-review-queue__grid .cbf-grid-link {
  color: inherit;
  text-decoration: none;
  border-radius: var(--radius-100, 4px);
}
.cbf-invoice-review-queue__grid .cbf-grid-link:hover {
  color: var(--color-background-brand);
  text-decoration: underline;
}
.cbf-invoice-review-queue__grid .cbf-grid-link:focus-visible {
  outline: 2px solid var(--color-background-brand);
  outline-offset: 2px;
}
.cbf-invoice-review-queue__grid .cbf-grid-peek {
  display: flex;
  align-items: center;
  justify-content: center;
}
.cbf-invoice-review-queue__grid .cbf-grid-peek__btn {
  display: inline-flex;
  color: var(--color-content-default-tertiary);
  opacity: 0;
  transition: opacity 0.12s ease;
}
.cbf-invoice-review-queue__grid .ag-row:hover .cbf-grid-peek__btn,
.cbf-invoice-review-queue__grid .cbf-grid-peek__btn:focus-within {
  opacity: 1;
}
@media (hover: none) {
  .cbf-invoice-review-queue__grid .cbf-grid-peek__btn {
    opacity: 1;
  }
}
.cbf-invoice-doc__items tbody td {
  font-size: var(--font-size-150);
}
.cbf-invoice-review-queue__header {
  align-items: center;
  gap: var(--spacing-400);
  flex-wrap: wrap;
}
.cbf-invoice-review-queue__search {
  flex: 1 1 280px;
  max-width: 440px;
  min-width: 220px;
}
.cbf-invoice-review-queue__controls {
  display: flex;
  align-items: center;
  gap: var(--spacing-300) var(--spacing-400);
  flex-wrap: wrap;
}
.cbf-invoice-review-queue__controls-end {
  margin-left: auto;
}
.cbf-invoice-review-queue__controls-end:empty {
  display: none;
}
.cbf-invoice-review-queue__grid {
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-200);
  overflow: hidden;
  background: var(--color-background-elevation-raised);
}
.cbf-invoice-review-queue__footer {
  color: var(--color-content-default-tertiary);
}
.cbf-review-dialog {
  --side-dialog-width-lg: max(1180px, 75vw);
}
.cbf-review-dialog__titlebar {
  flex: 1;
  min-width: 0;
  text-align: right;
}
.cbf-review-dialog__title {
  font-size: var(--font-size-500);
  font-weight: var(--typography-font-weight-bold);
  color: var(--color-content-default);
  font-variant-numeric: tabular-nums;
}
.cbf-review__label {
  font-size: var(--font-size-150);
  font-weight: var(--typography-font-weight-medium);
  color: var(--color-content-default-tertiary);
}
.cbf-review__section-title {
  margin: 0;
  font-size: var(--font-size-150);
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default-tertiary);
}
.cbf-review-hero {
  align-items: flex-start;
  gap: var(--spacing-400);
}
.cbf-review-hero__status {
  flex: none;
}
.cbf-review-deadline {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-100);
  min-width: 0;
}
.cbf-review-deadline__date {
  font-size: var(--font-size-500);
  font-weight: var(--typography-font-weight-bold);
  line-height: var(--line-height-tight);
  color: var(--color-content-default);
  font-variant-numeric: tabular-nums;
}
.cbf-review-deadline__urgency {
  display: block;
}
.cbf-review-deadline__urgency:empty {
  display: none;
}
.cbf-review-deadline__support {
  margin: var(--spacing-100) 0 0;
  font-size: var(--font-size-100);
  color: var(--color-content-default-tertiary);
}
.cbf-review-money {
  padding-block: var(--spacing-200);
  border-block: 1px solid var(--color-border-default);
}
.cbf-review-money__amount {
  font-size: var(--font-size-400);
  font-weight: var(--typography-font-weight-medium);
  color: var(--color-content-default);
}
.cbf-review-fields {
  margin: 0;
}
.cbf-review-fields__row {
  display: grid;
  grid-template-columns: 92px 1fr auto;
  gap: var(--spacing-300);
  align-items: baseline;
  padding-block: var(--spacing-250);
  border-top: 1px solid var(--color-border-default-subtle, var(--color-border-default));
}
.cbf-review-fields__row:first-child {
  border-top: 0;
  padding-top: 0;
}
.cbf-review-fields__value {
  margin: 0;
  font-size: var(--font-size-200);
  color: var(--color-content-default-secondary);
}
.cbf-review-fields__sub {
  display: block;
  margin-top: var(--spacing-050);
  font-size: var(--font-size-100);
  font-weight: var(--typography-font-weight-regular);
  color: var(--color-content-default-tertiary);
}
.cbf-review-fields__copy {
  align-self: center;
  position: relative;
  line-height: 0;
  color: var(--color-content-default-tertiary);
}
.cbf-review-fields__copy .esa-icon-button {
  color: inherit;
}
.cbf-review-fields__copy .esa-icon-button:hover {
  background: color-mix(in srgb, var(--color-content-default-tertiary) 14%, transparent);
  color: var(--color-content-default);
}
.cbf-review-fields__copy[data-state="copied"] {
  color: var(--color-content-utility-success);
}
.cbf-review-fields__copy[data-state="copied"]:after {
  content: "Copied";
  position: absolute;
  right: calc(100% + var(--spacing-150));
  top: 50%;
  transform: translateY(-50%);
  white-space: nowrap;
  font-size: var(--font-size-050);
  font-weight: var(--typography-font-weight-medium);
  color: var(--color-content-utility-success);
  pointer-events: none;
}
.cbf-review-attachments {
  margin-top: var(--spacing-200);
}
.cbf-review-attachments__head {
  align-items: center;
  gap: var(--spacing-300);
  margin-bottom: var(--spacing-300);
}
.cbf-review-attachments__head .cbf-review__section-title {
  margin: 0;
}
.cbf-review-attachments__list {
  list-style: none;
  margin: 0;
  padding: 0;
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-200);
  overflow: hidden;
}
.cbf-review-process {
  display: flex;
  justify-content: flex-end;
  margin-top: var(--spacing-200);
}
.cbf-review-split {
  min-height: 100%;
}
.cbf-review-docpane {
  background: var(--color-background-elevation-sunken);
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-200);
  display: flex;
  flex-direction: column;
  min-height: 0;
  overflow: hidden;
}
.cbf-review-docpane__scroll {
  flex: 1;
  min-height: 0;
  padding: var(--spacing-600);
  display: flex;
  flex-direction: column;
  align-items: center;
  overflow-y: auto;
}
.cbf-invoice-doc {
  position: relative;
  flex: 1 0 auto;
  width: 100%;
  max-width: 620px;
  background: var(--color-background-elevation-raised);
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-100);
  box-shadow: 0 1px 4px
    color-mix(in srgb, var(--color-background-default-knockout) 10%, transparent);
  padding: var(--spacing-700) var(--spacing-700) var(--spacing-600);
  color: var(--color-content-default);
  font-size: var(--font-size-150);
  line-height: var(--line-height-normal);
}
.cbf-invoice-doc__stamp {
  position: absolute;
  top: var(--spacing-500);
  right: var(--spacing-500);
  font-size: var(--font-size-100);
  font-weight: var(--typography-font-weight-semibold);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--color-background-utility-danger, #b42318);
  border: 1.5px solid currentColor;
  border-radius: var(--radius-100);
  padding: 2px var(--spacing-200);
  transform: rotate(-4deg);
  opacity: 0.8;
}
.cbf-invoice-doc__head {
  display: flex;
  justify-content: space-between;
  gap: var(--spacing-400);
  align-items: flex-start;
  margin-bottom: var(--spacing-500);
}
.cbf-invoice-doc__vendor {
  margin: 0;
  font-size: var(--font-size-400);
  font-weight: var(--typography-font-weight-bold);
}
.cbf-invoice-doc__sub {
  margin: 0;
  color: var(--color-content-default-tertiary);
  font-size: var(--font-size-100);
}
.cbf-invoice-doc__meta {
  text-align: right;
}
.cbf-invoice-doc__meta p {
  margin: 0 0 var(--spacing-100);
}
.cbf-invoice-doc__meta span {
  color: var(--color-content-default-tertiary);
  margin-right: var(--spacing-200);
}
.cbf-invoice-doc__billto {
  margin-bottom: var(--spacing-500);
}
.cbf-invoice-doc__billto p {
  margin: 0;
}
.cbf-invoice-doc__items {
  width: 100%;
  border-collapse: collapse;
}
.cbf-invoice-doc__items th,
.cbf-invoice-doc__items td {
  text-align: left;
  padding: var(--spacing-250) 0;
  vertical-align: top;
}
.cbf-invoice-doc__items thead th {
  border-bottom: 1px solid var(--color-content-default);
  font-weight: var(--typography-font-weight-semibold);
  font-size: var(--font-size-100);
  color: var(--color-content-default-secondary);
}
.cbf-invoice-doc__items tbody tr + tr td {
  border-top: 1px solid var(--color-border-default-subtle, var(--color-border-default));
}
.cbf-invoice-doc__items tfoot th,
.cbf-invoice-doc__items tfoot td {
  padding: var(--spacing-150) 0;
  text-align: right;
}
.cbf-invoice-doc__items tfoot th {
  font-weight: var(--typography-font-weight-regular);
  color: var(--color-content-default-secondary);
}
.cbf-invoice-doc__items tfoot tr:first-child th,
.cbf-invoice-doc__items tfoot tr:first-child td {
  padding-top: var(--spacing-400);
}
.cbf-invoice-doc__total th,
.cbf-invoice-doc__total td {
  border-top: 1px solid var(--color-content-default);
  font-weight: var(--typography-font-weight-bold);
  font-size: var(--font-size-200);
  padding-top: var(--spacing-300) !important;
}
.cbf-invoice-doc .cbf-num {
  text-align: right;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.cbf-invoice-doc__items th.cbf-num {
  text-align: right;
}
.cbf-invoice-doc__memo {
  margin: var(--spacing-600) 0 0;
  color: var(--color-content-default-secondary);
  line-height: var(--line-height-relaxed);
}
.cbf-invoice-doc__memo span {
  color: var(--color-content-default-tertiary);
}
.cbf-invoice-doc__generated {
  margin: var(--spacing-600) 0 0;
  padding-top: var(--spacing-400);
  border-top: 1px solid var(--color-border-default-subtle, var(--color-border-default));
  color: var(--color-content-default-tertiary);
  font-size: var(--font-size-100);
  font-style: italic;
}
.cbf-review-footer {
  align-items: center;
  gap: var(--spacing-400);
  width: 100%;
}
.cbf-review-footer__position {
  font-size: var(--font-size-150);
  color: var(--color-content-default-tertiary);
  font-variant-numeric: tabular-nums;
}
.esa-nav-dropdown .esa-button__native > .esa-icon:last-child {
  transition: transform 0.15s ease;
}
.esa-nav-dropdown[open] .esa-button__native > .esa-icon:last-child {
  transform: rotate(180deg);
}
.cbf-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: none;
  color: inherit;
}
.cbf-search-surface .cbf-icon {
  display: inline-flex;
  align-items: center;
}
.cbf-search-surface .cbf-result-group__title .cbf-icon {
  color: var(--color-content-default-tertiary);
}
.cbf-person-card .cbf-icon {
  display: inline-flex;
  align-items: center;
}
.cbf-person-card__label .cbf-icon {
  color: var(--color-background-brand-muted);
}
.cbf-nav-link .cbf-icon {
  display: inline-flex;
  align-items: center;
}
.esa-icon {
  --_icon-size: var(--icon-size-md, 20px);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--_icon-size);
  height: var(--_icon-size);
